INSERT INTO `activities` (`id`, `category_id`, `title`, `description`, `cover_image`, `pdf_file`, `excel_file`, `participants_count`, `activity_date`, `location`, `status`, `created_at`, `updated_at`) VALUES
(7, 6, 'องค์กรจัดอบรมความปลอดภัยทางเว็ป เพื่อเสริมสร้างความรู้ให้กับนักศึกษา', 'การจัดอบรมความปลอดภัยทางเว็ปเป็นส่วนสำคัญในการพัฒนาบุคลากรในองค์กร ช่วยให้พนักงานเข้าใจถึงความเสี่ยงจากการใช้งานอินเทอร์เน็ตในชีวิตประจำวัน เนื้อหาครอบคลุมทั้งการป้องกันไวรัส มัลแวร์ และการโจมตีทางไซเบอร์ รวมถึงแนวทางปฏิบัติเมื่อพบเหตุการณ์ผิดปกติบนเว็ปไซต์ ส่งผลให้องค์กรมีความปลอดภัยด้านข้อมูลมากยิ่งขึ้น', 'covers/p6h1S8G2ZgGvLmBefSNECDRqmPSj4sy7bakRwv4l.png', 'pdfs/iJnZDu0AbKNUEjNapQZxAFzYwHaS6pjjCaZpNQ8h.pdf', NULL, 0, '2026-04-07', 'ตึกหอสมุด ชั้น 2', 1, '2026-04-10 08:17:53', '2026-04-10 09:11:31'),
(8, 7, 'การทำจิตอาสาช่วยเสริมสร้างความสัมพันธ์ในสังคม', 'กิจกรรมจิตอาสาเป็นโอกาสให้ผู้คนได้รู้จักและสร้างมิตรภาพใหม่\r\nช่วยเชื่อมความสัมพันธ์ระหว่างคนในชุมชนและต่างวัย\r\nทำให้เกิดความเข้าใจและความร่วมมือกันมากขึ้น\r\nลดช่องว่างทางสังคมและสร้างบรรยากาศที่ดี\r\nส่งผลให้สังคมมีความเข้มแข็งและยั่งยืน', 'covers/1JDODTWvXPeiHwC88XMJ9GcZEbgHPUAnLewOZUpk.jpg', 'pdfs/3gLCOqMvcZyfIRbtrCIEAyhbomvC7XUNkNkGFIXh.pdf', 'excels/R3vKwyyIsq4glUS2wpUAxTbqX99o1MZcc2EOpKZC.xlsx', 15, '2026-04-10', 'หอประชุมช้าง', 1, '2026-04-10 09:16:06', '2026-04-24 05:38:58'),
(10, 6, 'อมรมความรู้การใช้โซเชียว', 'อมรมความรู้การใช้สื่อโซเชียวมีเดีย', 'covers/3Hcx48fQntODu3zeaupfTEisTKEIgUhpIetTxCN7.png', 'pdfs/NRP20KjKTZCe5xerz7s4Vbdi5HjmfMSlLLp4xRKH.pdf', 'excels/HxpfQl4gRGi6L6wCkty74ZdZpv7Oyigve32NOqIJ.xlsx', 15, '2023-02-24', 'ตึกห้องสมุดชั้น 3', 1, '2026-04-24 05:09:55', '2026-04-24 05:44:04');
